def semear(sessao):
    for dados in TEMAS:
        existente=sessao.get(Tema,dados['codigo'])
        if existente:
            if existente.nome != dados['nome']:
                raise ValueError('Código de tema já utilizado: '+dados['codigo'])
            continue  # inclusive desativação: a carga nunca reativa nem reutiliza códigos
        sessao.add(Tema(**dados,ativo=True))
    sessao.flush()
